legacyStyles:
/* =========================================================
   全局 UI 样式（原 global.css 内联）
   ========================================================= */
:root{--paper:#f5f1e8;--ink:#1a1a1a;--red:#a02020;--gold:#b8860b;--gray:#6b6b6b;--line:#c9c2b3;--bg-dark:#2a2520;--quote-bg:#ede8db}
*{margin:0;padding:0;box-sizing:border-box}
body{background:var(--paper);color:var(--ink);font-family:Georgia,'Times New Roman','Songti SC','SimSun',serif;line-height:1.85;font-size:18px;-webkit-font-smoothing:antialiased;padding-top:76px;overflow-x:hidden}
.masthead .brand,.top-bar .brand{white-space:nowrap;flex-shrink:0}
.masthead .date,.top-bar .pos{white-space:nowrap;margin-left:auto}
.top-bar .toc{white-space:nowrap}
.internal-banner{position:fixed;top:0;left:0;right:0;background:var(--red);color:#fff;text-align:center;padding:8px 14px;font-size:12px;letter-spacing:3px;z-index:9999;font-weight:700}
.top-bar{position:fixed;top:33px;left:0;right:0;z-index:9998;background:var(--paper);border-bottom:1px solid var(--ink);font-family:Georgia,'Times New Roman','Songti SC','SimSun',serif}
.top-bar-inner{max-width:1200px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;padding:9px 32px;font-size:12px;letter-spacing:.5px;color:var(--ink)}
.top-bar-left,.top-bar-right{display:flex;align-items:center;gap:18px;flex-shrink:0}
.top-bar .home{display:inline-flex;align-items:center;color:var(--red);text-decoration:none;border:1px solid var(--red);padding:4px 12px;border-radius:2px;font-size:12px;letter-spacing:1px;transition:background .2s,color .2s;white-space:nowrap}
.top-bar .home::before{content:"\2190";margin-right:6px}
.top-bar .home:hover{background:var(--red);color:var(--paper)}
.top-bar .time{color:var(--gray);font-size:12px;letter-spacing:.5px}
.top-bar .pos{color:var(--ink);font-size:12px;letter-spacing:.5px}
.top-bar .pos b{color:var(--red);font-weight:700}
.top-bar .sep{width:1px;height:14px;background:var(--line)}
.top-bar .toc{background:var(--bg-dark);color:var(--paper);border:none;padding:5px 14px;border-radius:2px;font-size:12px;letter-spacing:1px;cursor:pointer;font-family:Georgia,serif;transition:background .15s;white-space:nowrap}
.top-bar .toc:hover{background:var(--red)}
.progress-bar{position:fixed;top:70px;left:0;height:3px;background:var(--red);z-index:1000;transition:width .1s,top .2s}
.scroll-target,h2,.epilogue{scroll-margin-top:80px}
.hero h1,.hero{scroll-margin-top:80px}
.top-bar .home,.top-bar .toc,.top-bar .pos{display:inline-flex;align-items:center;line-height:1.3}
.compact .internal-banner{display:none}
.compact .top-bar{top:0;left:0;right:0;background:var(--red);border-bottom:none;z-index:9999;transition:top .3s,background .3s}
.compact .top-bar-inner{padding:4px 24px;position:relative;transition:padding .3s}
.compact .top-bar-inner::before{content:"● 内部资料 \00B7 仅供研究参考 \00B7 请勿外传";position:absolute;left:50%;transform:translateX(-50%);font-size:10px;letter-spacing:1px;color:#fff;white-space:nowrap;pointer-events:none;opacity:.7}
.compact .top-bar .home{color:#fff;border-color:rgba(255,255,255,.6);padding:3px 10px;font-size:11px}
.compact .top-bar .home::before{content:"\2190"}
.compact .top-bar .home:hover{background:#fff;color:var(--red)}
.compact .top-bar .time{display:none}
.compact .top-bar .toc{display:none}
.compact .top-bar .pos{color:#fff;font-size:11px;cursor:pointer;background:rgba(255,255,255,.15);padding:4px 10px;border-radius:2px;transition:background .15s}
.compact .top-bar .pos:hover{background:rgba(255,255,255,.3)}
.compact .top-bar .pos b{color:#fff}
.compact .top-bar .sep{background:rgba(255,255,255,.35);height:12px}
.compact .top-bar .toc{background:rgba(255,255,255,.25);color:#fff;padding:4px 10px;font-size:11px;cursor:pointer;position:relative;z-index:10;pointer-events:auto;white-space:nowrap}
.compact .top-bar .toc:hover{background:rgba(255,255,255,.4)}
.compact .progress-bar{top:30px;transition:top .3s,width .1s}
.hero + h2{border-top:none !important;padding-top:0 !important}
body.locked{overflow:hidden}
.consent-overlay{position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:20000;display:flex;align-items:center;justify-content:center;padding:20px;opacity:0;visibility:hidden;transition:opacity .25s}
.consent-overlay.show{opacity:1;visibility:visible}
.consent-box{background:#fbf8f0;max-width:580px;width:100%;border-radius:6px;box-shadow:0 16px 48px rgba(0,0,0,.25);max-height:88vh;overflow-y:auto}
.consent-header{background:var(--red);color:#fff;padding:18px 24px;font-size:18px;font-weight:700;letter-spacing:1px;border-radius:6px 6px 0 0;display:flex;justify-content:space-between;align-items:center}
.consent-body{padding:22px 24px 16px;font-size:14px;line-height:1.85;color:#333}
.consent-body h3{font-size:14px;color:var(--red);margin:18px 0 8px;letter-spacing:1px}
.consent-body h3:first-child{margin-top:0}
.consent-body ul{margin:8px 0 0 18px;padding:0}
.consent-body li{margin-bottom:6px}
.consent-body b{color:var(--ink)}
.consent-footer{padding:16px 24px 22px;border-top:1px solid var(--line);display:flex;flex-direction:column;gap:14px}
.consent-agree{display:flex;align-items:center;gap:10px;font-size:14px;color:var(--ink);cursor:pointer;user-select:none;padding:11px 14px;border:1px solid var(--line);border-radius:6px;background:#fff;transition:border-color .15s}
.consent-agree:hover{border-color:var(--red)}
.consent-agree input{width:18px;height:18px;flex-shrink:0;accent-color:var(--red);cursor:pointer;margin:0}
.consent-btn{width:100%;background:var(--red);color:#fff;border:none;padding:13px 20px;font-size:15px;font-weight:700;letter-spacing:2px;border-radius:6px;cursor:pointer;transition:background .15s}
.consent-btn:hover{background:#8a1818}
.consent-btn:disabled{background:#cfc7b8;cursor:not-allowed}
.consent-close{background:none;border:none;color:#fff;font-size:22px;cursor:pointer;padding:0 6px;line-height:1}
.consent-close:hover{opacity:.8}
footer{border-top:3px double var(--ink);margin-top:40px;padding:26px 0 50px;font-size:12px;color:var(--gray);line-height:1.7}
footer .disc{margin:0 auto;max-width:680px;border:1px solid var(--line);border-radius:4px;padding:14px 24px;background:#fbf8f0}
footer .disc b{color:var(--ink);font-weight:700;display:block;margin-bottom:6px;font-size:13px;letter-spacing:1px}
footer .foot-meta{margin:14px auto 0;max-width:680px;text-align:center;font-size:12px;color:var(--gray);letter-spacing:.5px}
footer .foot-meta b{color:var(--red);font-weight:700}
footer .foot-meta a{color:var(--red);text-decoration:none;border-bottom:1px solid var(--red)}
footer .foot-meta a:hover{opacity:.75}
.sidenav{position:fixed;top:0;right:0;width:250px;height:100vh;background:rgba(245,241,232,.98);border-left:1px solid var(--line);padding:86px 18px 20px;overflow-y:auto;z-index:200;transform:translateX(100%);transition:transform .3s;box-shadow:-4px 0 20px rgba(0,0,0,.06)}
.sidenav.open{transform:translateX(0)}
.sidenav h4{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--gray);margin-bottom:14px;border-bottom:1px solid var(--line);padding-bottom:8px}
.sidenav .close{position:absolute;top:16px;right:16px;background:none;border:none;font-size:24px;color:var(--gray);cursor:pointer;font-family:Georgia,serif}
.sidenav a{display:block;color:var(--ink);text-decoration:none;font-size:13px;line-height:1.4;padding:8px;border-radius:2px;transition:all .2s;margin-bottom:2px}
.sidenav a:hover{background:rgba(160,32,32,.08);color:var(--red)}
.sidenav a.active{background:var(--red);color:var(--paper);font-weight:700}
.sidenav a .num{font-size:11px;color:var(--gray);display:block;margin-bottom:2px}
.sidenav a.active .num{color:rgba(255,255,255,.75)}
.back-top{position:fixed;bottom:20px;right:20px;width:44px;height:44px;background:var(--bg-dark);color:var(--paper);border:none;border-radius:50%;font-size:20px;cursor:pointer;z-index:100;opacity:0;transition:opacity .3s;font-family:Georgia,serif}
.back-top.visible{opacity:.85}
.back-top:hover{opacity:1;background:var(--red)}
.reading-time-fab{position:fixed;top:78px;right:16px;background:rgba(42,37,32,.88);color:var(--paper);padding:6px 12px;border-radius:16px;font-size:11px;letter-spacing:.5px;z-index:9999;font-family:Georgia,serif}
/* —— 试读标签 —— */
.tag{display:inline-block;color:var(--red);border:1px solid var(--red);font-size:10px;letter-spacing:1px;padding:2px 8px;margin-right:8px;vertical-align:middle;font-weight:400}
/* =========================================================
   页面专属样式
   ========================================================= */
.masthead{display:flex;justify-content:space-between;align-items:flex-end;padding:18px 24px 10px;border-bottom:3px double var(--ink);max-width:940px;margin:0 auto}
.masthead .brand{font-size:14px;letter-spacing:3px;text-transform:uppercase;color:var(--gray)}
.masthead .brand b{color:var(--red);font-weight:700}
.masthead .brand a{color:inherit;text-decoration:none}
.masthead .brand a:hover{color:var(--red)}
.masthead .date{font-size:12px;color:var(--gray);letter-spacing:1px}
.container{max-width:720px;margin:0 auto;padding:36px 24px 80px}
.hero{margin-bottom:46px}
.hero .kicker{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--red);border-bottom:1px solid var(--red);display:inline-block;padding-bottom:3px;margin-bottom:18px}
.hero h1{font-size:42px;font-weight:700;line-height:1.28;letter-spacing:-.5px;margin-bottom:16px}
.hero .dek{font-size:18px;color:var(--gray);line-height:1.6;margin-bottom:18px;font-style:normal}
.hero .byline{display:flex;justify-content:space-between;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:10px 0;font-size:12px;letter-spacing:1px;color:var(--gray)}
.hero .byline .meta{font-style:italic}
.drop-cap::first-letter{font-size:58px;float:left;line-height:1;margin:4px 10px 0 0;font-weight:700;color:var(--ink)}
h2{font-size:25px;font-weight:700;margin:50px 0 18px;padding-top:22px;border-top:1px solid var(--line);letter-spacing:-.3px}
h2 .chap-num{font-size:13px;color:var(--red);letter-spacing:2px;display:block;margin-bottom:4px}
h3{font-size:19px;font-weight:700;margin:32px 0 14px;color:var(--ink)}
h4{font-size:16px;font-weight:700;margin:24px 0 10px;color:var(--red)}
p{margin-bottom:18px;text-align:justify}
blockquote{background:var(--quote-bg);border-left:4px solid var(--red);padding:18px 24px;margin:24px 0;font-style:italic;font-size:17px;color:#3a3a3a}
.pull-quote{font-size:25px;font-style:italic;color:var(--red);text-align:center;margin:36px 20px;line-height:1.5;padding:20px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
table{width:100%;border-collapse:collapse;margin:24px 0;font-size:15px}
th{background:var(--bg-dark);color:var(--paper);padding:10px 12px;text-align:left;font-size:13px;letter-spacing:.5px}
td{padding:9px 12px;border-bottom:1px solid var(--line)}
tr:nth-child(even){background:rgba(0,0,0,.02)}
td strong{color:var(--red)}
ul,ol{margin:18px 0 18px 24px}
li{margin-bottom:10px}
.data-callout{display:flex;flex-wrap:wrap;gap:16px;margin:28px 0}
.data-card{flex:1;min-width:140px;background:var(--bg-dark);color:var(--paper);padding:18px;border-radius:2px;text-align:center}
.data-card .num{font-size:27px;font-weight:700;color:#e8c87a;display:block}
.data-card .label{font-size:12px;letter-spacing:1px;margin-top:6px;opacity:.8;line-height:1.4}
.timeline{margin:28px 0;padding-left:20px;border-left:3px solid var(--red)}
.timeline-item{margin-bottom:20px;position:relative}
.timeline-item::before{content:'';position:absolute;left:-26px;top:8px;width:10px;height:10px;background:var(--red);border-radius:50%}
.timeline-date{font-size:13px;color:var(--red);font-weight:700;letter-spacing:1px}
.timeline-content{margin-top:4px}
.footnotes{margin-top:60px;padding-top:24px;border-top:2px solid var(--ink)}
.footnotes h3{font-size:16px;letter-spacing:1px;text-transform:uppercase}
.footnotes ol{font-size:13px;color:var(--gray);line-height:1.7}
.footnotes li{margin-bottom:7px}
sup{font-size:11px;color:var(--red);cursor:pointer}
.epilogue{background:var(--bg-dark);color:#e8e2d4;padding:40px 34px;margin:40px -24px 0;border-radius:2px}
.epilogue h2{border-top:none;color:#e8c87a;padding-top:0;font-size:24px}
.epilogue p{color:#ddd8cc;line-height:1.9;margin-bottom:16px}
.epilogue .drop-cap::first-letter{color:#e8c87a;font-size:48px}
.epilogue .pull-quote{color:#e8c87a;border-color:#5a5045;font-size:22px}
.epilogue strong{color:#e8c87a}
.disclaimer{font-size:12px;color:var(--gray);margin-top:30px;line-height:1.6;text-align:center}
.term{border-bottom:1px dotted var(--red);cursor:help;color:var(--red);font-weight:600}
.chart-box{margin:28px 0;padding:20px;border:1px solid var(--line);background:rgba(255,255,255,.4)}
.chart-title{font-size:14px;font-weight:700;letter-spacing:.5px;margin-bottom:4px;color:var(--bg-dark);text-align:center}
.chart-sub{font-size:11px;color:var(--gray);text-align:center;margin-bottom:14px}
.bar-chart{display:flex;flex-direction:column;gap:14px}
.bar-row{display:flex;align-items:center;gap:10px}
.bar-label{width:96px;font-size:13px;font-weight:700;text-align:right;flex-shrink:0}
.bar-track{flex:1;background:var(--quote-bg);height:30px;position:relative;overflow:hidden}
.bar-fill{height:100%;display:flex;align-items:center;padding-left:10px;color:var(--paper);font-size:12px;font-weight:700;white-space:nowrap;width:0;transition:width 1.2s cubic-bezier(.4,0,.2,1)}
.bar-fill.red{background:var(--red)}
.bar-fill.dark{background:#4a4036}
.bar-fill.gray{background:#8a8073}
.bar-fill.gold{background:var(--gold)}
.bar-fill.green{background:#5a9e6f}
.bar-value{width:110px;font-size:11px;color:var(--gray);flex-shrink:0;line-height:1.3}
.step-chart{display:flex;align-items:flex-end;justify-content:space-around;height:200px;gap:8px;padding:0 4px;border-bottom:2px solid var(--bg-dark)}
.step-col{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;flex:1;max-width:90px}
.step-value{font-size:11px;font-weight:700;margin-bottom:4px;color:var(--bg-dark)}
.step-bar{width:100%;background:var(--bg-dark);border-radius:2px 2px 0 0;height:0;transition:height 1s cubic-bezier(.4,0,.2,1);display:flex;align-items:flex-start;justify-content:center;padding-top:6px;color:#e8c87a;font-size:12px;font-weight:700;min-height:0}
.step-bar.red{background:var(--red)}
.step-bar.green{background:#5a9e6f}
.step-bar.gold{background:var(--gold)}
.step-label{font-size:10px;margin-top:6px;text-align:center;color:var(--ink);line-height:1.3}
.vert-bars{display:flex;align-items:flex-end;justify-content:space-around;height:200px;padding:0 8px;border-bottom:2px solid var(--bg-dark);gap:6px}
.vert-bar-wrap{display:flex;flex-direction:column;align-items:center;flex:1;max-width:80px}
.vert-bar-wrap .val{font-size:10px;font-weight:700;margin-bottom:4px;color:var(--bg-dark)}
.vert-bar-wrap .bar{width:100%;background:var(--bg-dark);border-radius:2px 2px 0 0;display:flex;align-items:flex-start;justify-content:center;padding-top:4px;color:#e8c87a;font-size:10px;font-weight:700;transition:height 1.2s cubic-bezier(.4,0,.2,1);height:0}
.vert-bar-wrap .bar.bull{background:var(--red)}
.vert-bar-wrap .bar.bull-peak{background:var(--gold)}
.vert-bar-wrap .yr{font-size:10px;margin-top:4px;color:var(--gray)}
.di-wrap{display:flex;align-items:center;justify-content:center;gap:20px;flex-wrap:wrap;margin:20px 0}
.di-svg-wrap{position:relative;width:220px;height:220px;flex-shrink:0}
.di-svg{width:100%;height:100%;transform:rotate(-90deg);overflow:visible}
.di-seg{fill:none;stroke-width:28;cx:110;cy:110;r:82;stroke-linecap:butt;cursor:pointer;transition:stroke-dasharray 1.1s,stroke-opacity .3s,stroke-width .2s}
.di-seg.dim{stroke-opacity:.22}
.di-seg.on{stroke-width:34}
.di-center{position:absolute;top:110px;left:110px;transform:translate(-50%,-50%);text-align:center;z-index:2;pointer-events:none}
.di-center .big{font-size:24px;font-weight:700;color:var(--red);display:block}
.di-center .sub{font-size:11px;color:var(--gray);display:block;margin-top:2px}
.di-legend{font-size:13px;line-height:2.2;padding:4px 0}
.di-legend .di-item{cursor:pointer;transition:opacity .25s;display:flex;align-items:center;gap:8px;padding:2px 6px;border-radius:3px}
.di-legend .di-item.dim{opacity:.25}
.di-legend .di-item .dot{width:12px;height:12px;border-radius:3px;flex-shrink:0;display:inline-block}
.di-legend .di-item .name{flex-shrink:0}
.di-legend .di-item .val{font-weight:700;color:var(--ink)}
.di-callout{opacity:0;transition:opacity .4s;transition-delay:0s}
.di-callout.on{opacity:1;transition-delay:.5s}
.di-callout line{stroke:var(--gray);stroke-width:1;stroke-dasharray:3 2}
.di-callout text{font-size:11px;fill:var(--gray);font-family:Georgia,serif}
.di-callout text.on{fill:var(--red);font-weight:700}
.dist-bar{display:flex;height:32px;border-radius:3px;overflow:hidden;margin:14px 0}
.dist-seg{display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:var(--paper);transition:width 1s}
.two-col{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:24px 0}
.fn-tooltip{position:fixed;max-width:340px;background:var(--bg-dark);color:#e8e2d4;padding:12px 16px;font-size:12.5px;line-height:1.6;border-radius:3px;z-index:500;box-shadow:0 6px 24px rgba(0,0,0,.4);display:none;pointer-events:none}
.reveal{opacity:1;transform:none}.js .reveal{opacity:0;transform:translateY(20px);transition:opacity .6s,transform .6s}
.js .reveal.visible{opacity:1;transform:translateY(0)}
.line-chart{margin:20px 0}
.line-chart-svg{width:100%;height:auto;overflow:visible}
.line-a{fill:none;stroke:var(--red);stroke-width:2.5;stroke-dasharray:1000;stroke-dashoffset:1000;transition:stroke-dashoffset 2s ease}
.line-a.drawn{stroke-dashoffset:0}
.line-b{fill:none;stroke:var(--bg-dark);stroke-width:2.5;stroke-dasharray:1000;stroke-dashoffset:1000;transition:stroke-dashoffset 2s ease}
.line-b.drawn{stroke-dashoffset:0}
.dot-a,.dot-b{opacity:0;transition:opacity .4s}
.dot-a.visible,.dot-b.visible{opacity:1}
.chart-legend{display:flex;gap:20px;justify-content:center;margin:10px 0;font-size:12px}
.chart-legend-item{display:flex;align-items:center;gap:6px}
.chart-legend-dot{width:14px;height:4px;border-radius:2px}
.org-tree{display:flex;flex-direction:column;align-items:center;gap:6px;margin:20px 0}
.org-top{background:var(--bg-dark);color:var(--paper);padding:12px 24px;border-radius:3px;font-size:14px;font-weight:700;letter-spacing:.5px;text-align:center}
.org-arrow{font-size:18px;color:var(--red);line-height:1}
.org-row{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
.org-node{background:var(--red);color:var(--paper);padding:10px 18px;border-radius:3px;font-size:12px;text-align:center;line-height:1.4;min-width:120px}
.org-node.dark{background:var(--bg-dark)}
@media(max-width:600px){
  body{font-size:16px}
  .container{padding:24px 16px 60px}
  .hero h1{font-size:28px}
  .hero .dek{font-size:15px}
  .masthead{padding:10px 16px}
  .masthead .brand{font-size:10px;letter-spacing:2px}
  .masthead .date{font-size:10px}
  .pull-quote{font-size:19px}
  .data-card{min-width:120px}
  .epilogue{margin:30px -16px 0}
  .bar-label{width:70px;font-size:11px}
  .bar-value{width:80px;font-size:10px}
  .bar-fill{font-size:10px}
  .step-label{font-size:9px}
  .step-value{font-size:10px}
  .di-wrap{flex-direction:column}
  .step-chart{height:150px}
  .vert-bars{height:150px}
  .two-col{grid-template-columns:1fr}
  .reading-time-fab{top:12px;right:12px}
  .consent-body{padding:16px 18px}
  .consent-header{font-size:16px;padding:14px 18px}
  .top-bar-inner{padding:8px 12px}
  .top-bar .sep{display:none}
  .top-bar .time{display:none}
  .top-bar .home{border:none;padding:3px 8px;font-size:11px;letter-spacing:.5px}
  .top-bar .home::before{content:"\2190";margin-right:4px}
  .top-bar .toc{padding:4px 10px;font-size:11px;letter-spacing:.5px}
  .top-bar-left,.top-bar-right{gap:6px}
  .top-bar .pos{font-size:11px}
  .compact .internal-banner{display:none}
  .compact .top-bar{top:0}
